file.content:
    parsed = parseYaml(yamlContent);
  } catch (err) {
    errors.push({
      type: "yaml",
      message: `Malformed YAML in Specs section: ${err instanceof Error ? err.message : String(err)}`,
    });
    return [];
  }

  // Validate array
  if (!Array.isArray(parsed)) {
    errors.push({
      type: "validation",
      message: "Specs section must contain a YAML array",
    });
    return [];
  }

  // Validate each spec
  const specs: PlanSpec[] = [];

  for (let i = 0; i < parsed.length; i++) {
    const spec = parsed[i];

    // Validate required title field
    if (!spec || typeof spec !== "object" || !("title" in spec)) {
      errors.push({
        type: "validation",
        message: `Spec at index ${i} missing required field: title`,
        specIndex: i,
      });
      continue;
    }

    // Validate against schema
    const result = PlanSpecSchema.safeParse(spec);
    if (!result.success) {
      errors.push({
        type: "validation",
        message: `Spec at index ${i} validation failed: ${result.error.message}`,
        specIndex: i,
      });
      continue;
    }

    specs.push(result.data);
  }

  return specs;
}

