      "task list --json",
      tempDir,
    );
    const derivedTasks = tasks.filter(
      (t) => t.notes.length > 0 && t.notes[0].content.includes("Implementation notes"),
    );
    expect(derivedTasks).toHaveLength(2); // Both derived tasks should have notes
  });
});

