          tags: [],
          depends_on: [],
          implements: [],
          relates_to: [],
          tests: [],
          traits: spec.traits || [],
          notes: [],
        }) as LoadedSpecItem;
        createdSpecsMap.set(specSlug, dryRunSpec);
