          priority: undefined,
          tags: [],
          depends_on: [],
          implements: [],
          relates_to: [],
          tests: [],
          traits: spec.traits || [],
          notes: [],
        };

        // Add acceptance criteria if present
        if (spec.acceptance_criteria) {
