   198→
   199→    if (cmd.options.length > 0) {
   200→      console.log(chalk.gray("  Options:"));
   201→      for (const opt of cmd.options) {
   202→        console.log(
   203→          chalk.gray(`    ${opt.flags.padEnd(30)} ${opt.description}`),
   204→        );
   205→      }
   206→    }
   207→  }
   208→}
   209→
   210→/**
   211→ * Output help as JSON
   212→ */
   213→function showJson(): void {
   214→  const tree = extractCommandTree(program);
   215→
   216→  // Include both command tree and curated content
   217→  const data = {
   218→    commands: tree,
   219→    content: helpContent,
   220→  };
   221→
   222→  output(data);
   223→}
   224→
   225→/**
   226→ * Register the help command
   227→ */
   228→export function registerHelpCommand(program: Command): void {
   229→  program
   230→    .command("help [topic]")
   231→    .description("Extended help for commands and concepts")
   232→    .option("--all", "Show full command reference")
   233→    .option("--json", "Output as JSON")
   234→    .action((topic?: string, options?: { all?: boolean; json?: boolean }) => {
   235→      // Handle flags
   236→      if (options?.json) {
   237→        showJson();
   238→        return;
   239→      }
   240→
   241→      if (options?.all) {
   242→        showFullReference();
   243→        return;
   244→      }
   245→
   246→      // Show topic or list
   247→      if (topic) {
   248→        showTopic(topic);
   249→      } else {
   250→        showTopicList();
   251→      }
   252→    });
   253→}
