  for (const opt of command.options) {
    // Extract option name from flags (e.g., "-f, --force" -> "force")
    const flagMatch = opt.flags.match(/--([a-zA-Z0-9-]+)/);
    if (!flagMatch) continue;

    const propName = flagMatch[1];

