      type = "string";
    }

    const propSchema: Record<string, unknown> = {
      type,
      description: opt.description,
    };

    if (opt.defaultValue !== undefined) {
      propSchema.default = opt.defaultValue;
    }

    properties[propName] = propSchema;

    if (opt.required) {
      required.push(propName);
    }
  }

