      if (options?.json) {
        // AC: @cli-schema-introspection ac-5
        setJsonMode(true);
        showJson();
        return;
      }

      if (options?.all) {
        showFullReference();
        return;
      }

      // Show topic or list
      if (topic) {
        showTopic(topic);
      } else {
        showTopicList();
      }
    });
}

