describe('CLI schema introspection', () => {
  // AC: @cli-schema-introspection ac-1
  it('should output help as JSON with commands and content', () => {
    const result = kspecJson<{ commands: unknown; content: unknown }>(['help', '--json']);
    expect(result.exitCode).toBe(0);
    expect(result.data).toHaveProperty('commands');
    expect(result.data).toHaveProperty('content');
    expect(typeof result.data.commands).toBe('object');
    expect(typeof result.data.content).toBe('object');
  });

  // AC: @cli-schema-introspection ac-2
  it('should show exit codes in human-readable format', () => {
    const result = kspec(['help', '--exit-codes']);
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain('Exit Codes');
    expect(result.stdout).toContain('SUCCESS');
    expect(result.stdout).toContain('ERROR');
    expect(result.stdout).toContain('USAGE_ERROR');
    expect(result.stdout).toContain('NOT_FOUND');
    expect(result.stdout).toContain('VALIDATION_FAILED');
    expect(result.stdout).toContain('CONFLICT');
  });

  // AC: @cli-schema-introspection ac-3
  it('should output exit codes as JSON', () => {
    const result = kspecJson<Array<{ code: number; name: string; description: string; commands: string }>>([
      'help',
      '--exit-codes',
      '--json'
    ]);
    expect(result.exitCode).toBe(0);
    expect(Array.isArray(result.data)).toBe(true);
    expect(result.data.length).toBeGreaterThan(0);

    const successCode = result.data.find((ec) => ec.name === 'SUCCESS');
    expect(successCode).toBeDefined();
    expect(successCode?.code).toBe(0);
    expect(successCode?.description).toContain('success');
  });

  // AC: @cli-schema-introspection ac-4
  it('should output JSON Schema for a command', () => {
    const result = kspecJson<{
      $schema: string;
      type: string;
      title: string;
      properties: Record<string, unknown>;
    }>(['help', 'task', '--json-schema']);

    expect(result.exitCode).toBe(0);
    expect(result.data.$schema).toContain('json-schema.org');
    expect(result.data.type).toBe('object');
    expect(result.data).toHaveProperty('properties');
    expect(typeof result.data.properties).toBe('object');
  });

  // AC: @cli-schema-introspection ac-5
  it('should produce valid JSON without ANSI codes when --json is used', () => {
    const result = kspec(['help', '--json']);
    expect(result.exitCode).toBe(0);

    // Should be valid JSON
    expect(() => JSON.parse(result.stdout)).not.toThrow();

    // Should not contain ANSI escape codes
    expect(result.stdout).not.toMatch(/\x1b\[/);
  });
});

